# --- Formula cell functions ---

@xl_memoize
def output_scenarios_dspb_milestones_paris(ctx: EvalContext, fiscal_measure: str, time_period: int) -> int | float | CellValue:
    """Return the debt-stabilizing primary balance milestone for a given fiscal measure and time period under the Paris scenario.

Args:
    ctx: Workbook evaluation context.
    fiscal_measure: One of 'PB', 'PB*', or 'PB Gap'. Observed values: 'PB', 'PB*', 'PB Gap'.
    time_period: Projection year. Observed values: 2050, 2075, 2099.

Returns:
    float: The corresponding primary balance value as a percentage of GDP.

Note:
    Covers 'Output Scenarios'!F26:N26. Excel: ='Output Scenarios'!D6.
"""
    if fiscal_measure == 'PB':
        return output_scenarios_primary_balance_pct_gdp_summary_paris(ctx, time_period=time_period)
    if fiscal_measure == 'PB*':
        return scenario_debt_stabilizing_primary_balance_paris(ctx, time_period=time_period)
    dspb_pb_star = output_scenarios_dspb_milestones_paris(ctx, fiscal_measure='PB*', time_period=time_period)
    dspb_pb = output_scenarios_dspb_milestones_paris(ctx, fiscal_measure='PB', time_period=time_period)
    return xl_number(dspb_pb_star) - xl_number(dspb_pb)


@xl_memoize
def paris_engine_interest_expenditure_pct_revenue(ctx: EvalContext, time_period: int) -> float:
    """Compute interest expenditure as a percentage of revenue.

Args:
    ctx: Workbook evaluation context.
    time_period: The year for which to compute the percentage (range 2009-2099).

Returns:
    Interest expenditure as a percentage of revenue (float).

Note:
    Covers Paris!D37:CP37. Excel: =Paris!AA26/Paris!AA24*100.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        projected_interest_expenditure = paris_engine_indicators_2(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
        projected_revenue = paris_engine_revenue_lcu_2(ctx, time_period=time_period)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(projected_interest_expenditure), xl_number(projected_revenue))) * xl_number(100.0)
    actual_interest_expenditure = paris_engine_indicators(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
    actual_revenue = paris_engine_revenue_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(actual_interest_expenditure), xl_number(actual_revenue))) * xl_number(100.0)


