@xl_memoize
def paris_engine_primary_balance_lcu(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Computes the primary balance for the Paris scenario in billions of local currency units (LCU) for a given projection year.

Args:
    ctx: Workbook evaluation context.
    time_period (int): The projection year, typically in the range 2009 to 2099.

Returns:
    float: The primary balance in billions of LCU.

Note:
    Covers Paris!D28:CP28. Excel: =Paris!AA24-Paris!AA27.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        revenue = paris_engine_revenue_lcu_2(ctx, time_period=time_period)
        primary_expenditure = paris_engine_primary_expenditure_lcu(ctx, time_period=time_period)
        return xl_number(revenue) - xl_number(primary_expenditure)
    return baseline_engine_primary_balance_lcu(ctx, time_period=time_period)


@xl_memoize
def paris_engine_overall_balance_lcu(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Compute the overall balance for the Paris scenario in LCU.

Args:
    ctx: Workbook evaluation context, providing access to dependent series.
    time_period: Projection time period (year), ranging from 2009 to 2099.

Returns:
    Overall balance as a float in local currency units (LCU).

Note:
    Covers Paris!D29:CP29. Excel: =Paris!AA24-Paris!AA25.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        revenue_lcu = paris_engine_revenue_lcu_2(ctx, time_period=time_period)
        total_expenditure_lcu = paris_engine_indicators_2(ctx, indicator='total_expenditure_lcu', time_period=time_period)
        return xl_number(revenue_lcu) - xl_number(total_expenditure_lcu)
    return baseline_engine_overall_balance_lcu(ctx, time_period=time_period)


@xl_memoize
def scenario_debt_stabilizing_primary_balance_paris(ctx: EvalContext, time_period: int) -> float:
    """Computes the debt-stabilizing primary balance as a percent of GDP for the Paris scenario.

Args:
    ctx: Workbook evaluation context.
    time_period: The projection year (int, 2009 to 2099).

Returns:
    The required primary balance to stabilize debt, in percent of GDP. For 2009, returns an Excel #REF! error.

Note:
    Covers Paris!D36:CP36. Excel: =((Paris!AA32-Paris!AA11)/100)/(1+Paris!AA11/100)*Paris!Z35.
"""
    if time_period in {2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        later_weighted_interest_rate = paris_engine_weighted_interest_rate(ctx, time_period=time_period)
        later_nominal_gdp_growth = scenario_nominal_gdp_growth_paris(ctx, time_period=time_period)
        later_nominal_gdp_growth_2 = scenario_nominal_gdp_growth_paris(ctx, time_period=time_period)
        later_lagged_gross_debt_pct_gdp = paris_engine_indicators_2(ctx, indicator='gross_debt_pct_gdp', time_period=time_period - 1)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(later_weighted_interest_rate) - xl_number(later_nominal_gdp_growth)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(later_nominal_gdp_growth_2), xl_number(100.0)))))) * xl_number(later_lagged_gross_debt_pct_gdp)
    if time_period in {2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025, 2026, 2027, 2028, 2029, 2030}:
        mid_weighted_interest_rate = paris_engine_weighted_interest_rate(ctx, time_period=time_period)
        mid_nominal_gdp_growth = scenario_nominal_gdp_growth_paris(ctx, time_period=time_period)
        mid_nominal_gdp_growth_2 = scenario_nominal_gdp_growth_paris(ctx, time_period=time_period)
        mid_lagged_gross_debt_pct_gdp = paris_engine_indicators(ctx, indicator='gross_debt_pct_gdp', time_period=time_period - 1)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(mid_weighted_interest_rate) - xl_number(mid_nominal_gdp_growth)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(mid_nominal_gdp_growth_2), xl_number(100.0)))))) * xl_number(mid_lagged_gross_debt_pct_gdp)
    initial_weighted_interest_rate = paris_engine_weighted_interest_rate(ctx, time_period=2009)
    initial_nominal_gdp_growth = scenario_nominal_gdp_growth_paris(ctx, time_period=2009)
    initial_nominal_gdp_growth_2 = scenario_nominal_gdp_growth_paris(ctx, time_period=2009)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(initial_weighted_interest_rate) - xl_number(initial_nominal_gdp_growth)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(initial_nominal_gdp_growth_2), xl_number(100.0)))))) * xl_number(xl_raise(XlError.REF))


@xl_memoize
def output_scenarios_dspb_milestones_moderate(ctx: EvalContext, fiscal_measure: str, time_period: int) -> int | float | CellValue:
    """Compute debt-stabilizing primary balance milestone for the Moderate scenario.

Args:
    ctx: Workbook evaluation context.
    fiscal_measure: Fiscal measure key, one of 'PB', 'PB*', or 'PB Gap'.
    time_period: Projection time period (e.g., 2050, 2075, 2099).

Returns:
    Float: the milestone value. For 'PB', returns the primary balance summary;
    for 'PB*', the debt-stabilizing primary balance; for 'PB Gap', the difference
    (PB* minus PB).

Note:
    Covers 'Output Scenarios'!F27:N27. Excel: ='Output Scenarios'!D7.
"""
    if fiscal_measure == 'PB':
        return output_scenarios_primary_balance_pct_gdp_summary_moderate(ctx, time_period=time_period)
    if fiscal_measure == 'PB*':
        return scenario_debt_stabilizing_primary_balance_moderate(ctx, time_period=time_period)
    dspb_pb_star = output_scenarios_dspb_milestones_moderate(ctx, fiscal_measure='PB*', time_period=time_period)
    dspb_pb = output_scenarios_dspb_milestones_moderate(ctx, fiscal_measure='PB', time_period=time_period)
    return xl_number(dspb_pb_star) - xl_number(dspb_pb)


