@xl_memoize
def paris_engine_revenue_lcu_2(ctx: EvalContext, time_period: int) -> float:
    """Compute revenue in local currency units (LCU billions).

Args:
    ctx: Workbook evaluation context.
    time_period (int): Projection year (e.g., 2030..2099).

Returns:
    float: Revenue in LCU_BIL.

Note:
    Covers Paris!Y24:CP24. Excel: =Paris!AA17/100*Paris!AA13.
"""
    revenue_pct_gdp = paris_engine_revenue_pct_gdp(ctx, time_period=time_period)
    nominal_gdp_lcu = paris_engine_nominal_gdp_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(revenue_pct_gdp), xl_number(100.0))) * xl_number(nominal_gdp_lcu)


@xl_memoize
def paris_engine_primary_expenditure_lcu(ctx: EvalContext, time_period: int) -> int | float | CellValue:
    """Compute primary expenditure in local currency units (LCU) for the Paris scenario.

Args:
    ctx: Workbook evaluation context.
    time_period: Year for which the primary expenditure is computed (observed range: 2009..2099).

Returns:
    float: Primary expenditure in LCU.

Note:
    Covers Paris!D27:CP27. Excel: =Baseline!AA28-(1-Dashboard!C38)*(Baseline!AA28-(Paris!AA44/100*Paris!AA13))+Paris!AA41/100*Paris!AA13.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        baseline_primary_expenditure_lcu = baseline_engine_indicators_3(ctx, indicator='primary_expenditure_lcu', time_period=time_period)
        expenditure_rigidity = read_expenditure_rigidity(ctx)
        baseline_primary_expenditure_lcu_gap = baseline_engine_indicators_3(ctx, indicator='primary_expenditure_lcu', time_period=time_period)
        memo_primary_expenditure_pct_gdp = paris_engine_memo_primary_expenditure_pct_gdp(ctx, time_period=time_period)
        nominal_gdp_lcu = paris_engine_nominal_gdp_lcu(ctx, time_period=time_period)
        discrete_risk_expenditure_shock_pct = paris_engine_discrete_risk_expenditure_shock(ctx, time_period=time_period)
        nominal_gdp_lcu_shock = paris_engine_nominal_gdp_lcu(ctx, time_period=time_period)
        return xl_number(xl_number(baseline_primary_expenditure_lcu) - xl_number(xl_number(xl_number(1.0) - xl_number(expenditure_rigidity)) * xl_number(xl_number(baseline_primary_expenditure_lcu_gap) - xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(memo_primary_expenditure_pct_gdp), xl_number(100.0))) * xl_number(nominal_gdp_lcu))))) + xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(discrete_risk_expenditure_shock_pct), xl_number(100.0))) * xl_number(nominal_gdp_lcu_shock))
    return baseline_engine_indicators(ctx, indicator='primary_expenditure_lcu', time_period=time_period)


@xl_memoize
def paris_engine_nominal_gdp_lcu(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Computes nominal GDP in local currency units for the Paris scenario.

Args:
    ctx: Workbook evaluation context.
    time_period: The time period (year) for which to compute GDP. Expected range 2009-2099.

Returns:
    Nominal GDP in LCU billions as a float.

Note:
    Covers Paris!D13:CP13. Excel: =Paris!Z13*(1+Paris!AA11/100).
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        previous_nominal_gdp = paris_engine_nominal_gdp_lcu(ctx, time_period=time_period - 1)
        nominal_gdp_growth_rate = scenario_nominal_gdp_growth_paris(ctx, time_period=time_period)
        return xl_number(previous_nominal_gdp) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(nominal_gdp_growth_rate), xl_number(100.0))))
    return macrofiscal_nominal_gdp_lcu(ctx, time_period=time_period)


