        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(f6_weighted_interest_rate_2030), xl_number(100.0))) * xl_number(f6_gross_debt_lcu_2029)
