@xl_memoize
def moderate_engine_revenue_lcu_2(ctx: EvalContext, time_period: int) -> float:
    """Calculates engine revenue in local currency units (LCU) by applying revenue as a percentage of GDP to nominal GDP in LCU.

Args:
    ctx: Workbook evaluation context.
    time_period (int): Projection time period, observed range 2030..2099.

Returns:
    float: Engine revenue in LCU.

Note:
    Covers Moderate!Y24:CP24. Excel: =Moderate!AA17/100*Moderate!AA13.
"""
    revenue_pct_gdp = moderate_engine_revenue_pct_gdp(ctx, time_period=time_period)
    nominal_gdp_lcu = moderate_engine_nominal_gdp_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(revenue_pct_gdp), xl_number(100.0))) * xl_number(nominal_gdp_lcu)


@xl_memoize
def moderate_engine_primary_expenditure_lcu(ctx: EvalContext, time_period: int) -> int | float | CellValue:
    """Compute primary expenditure in local currency units for the moderate scenario.

Args:
    ctx: Evaluation context.
    time_period: Projection year (2009-2099).

Returns:
    Primary expenditure in local currency units.

Note:
    Covers Moderate!D27:CP27. Excel: =Baseline!AA28-(1-Dashboard!C38)*(Baseline!AA28-(Moderate!AA44/100*Moderate!AA13))+Moderate!AA41/100*Moderate!AA13.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        baseline_primary_expenditure = baseline_engine_indicators_3(ctx, indicator='primary_expenditure_lcu', time_period=time_period)
        expenditure_rigidity = read_expenditure_rigidity(ctx)
        baseline_primary_expenditure_blend = baseline_engine_indicators_3(ctx, indicator='primary_expenditure_lcu', time_period=time_period)
        primary_expenditure_pct_gdp = moderate_engine_memo_primary_expenditure_pct_gdp(ctx, time_period=time_period)
        nominal_gdp_lcu = moderate_engine_nominal_gdp_lcu(ctx, time_period=time_period)
        expenditure_shock_pct = moderate_engine_discrete_risk_expenditure_shock(ctx, time_period=time_period)
        nominal_gdp_lcu_for_shock = moderate_engine_nominal_gdp_lcu(ctx, time_period=time_period)
        return xl_number(xl_number(baseline_primary_expenditure) - xl_number(xl_number(xl_number(1.0) - xl_number(expenditure_rigidity)) * xl_number(xl_number(baseline_primary_expenditure_blend) - xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(primary_expenditure_pct_gdp), xl_number(100.0))) * xl_number(nominal_gdp_lcu))))) + xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(expenditure_shock_pct), xl_number(100.0))) * xl_number(nominal_gdp_lcu_for_shock))
    return baseline_engine_indicators(ctx, indicator='primary_expenditure_lcu', time_period=time_period)


@xl_memoize
def moderate_engine_nominal_gdp_lcu(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Computes the moderate scenario nominal GDP in local currency units (LCU).

Args:
    ctx: Workbook evaluation context.
    time_period: Projection year (2009-2099).

Returns:
    Nominal GDP in LCU.

Note:
    Covers Moderate!D13:CP13. Excel: =Moderate!Z13*(1+Moderate!AA11/100).
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        previous_nominal_gdp_lcu = moderate_engine_nominal_gdp_lcu(ctx, time_period=time_period - 1)
        nominal_gdp_growth_rate = scenario_nominal_gdp_growth_moderate(ctx, time_period=time_period)
        return xl_number(previous_nominal_gdp_lcu) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(nominal_gdp_growth_rate), xl_number(100.0))))
    return macrofiscal_nominal_gdp_lcu(ctx, time_period=time_period)


@xl_memoize
def scenario_real_gdp_level_index_moderate(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Returns the real GDP level index under the moderate scenario.

Args:
    ctx (EvalContext): Workbook evaluation context.
    time_period (int): The projection year, ranging from 2009 to 2099.

Returns:
    float: The real GDP level index under the moderate scenario.

Note:
    Covers Moderate!D14:CP14. Excel: =Moderate!Z14*(1+Moderate!AA9/100).
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        previous_real_gdp_index = scenario_real_gdp_level_index_moderate(ctx, time_period=time_period - 1)
        real_gdp_growth = moderate_engine_real_gdp_growth(ctx, time_period=time_period)
        return xl_number(previous_real_gdp_index) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(real_gdp_growth), xl_number(100.0))))
    return macrofiscal_real_gdp_lcu(ctx, time_period=time_period)


@xl_memoize
def scenario_nominal_gdp_growth_moderate(ctx: EvalContext, time_period: int) -> float:
    """Compute nominal GDP growth under the moderate scenario.

Args:
    time_period (int): Projection year, ranging from 2009 to 2099.

Returns:
    float: Nominal GDP growth in percent.

Note:
    Covers Moderate!D11:CP11. Excel: =(1+Moderate!AA9/100)*(1+Baseline!AA14/100)*100-100.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        real_gdp_growth = moderate_engine_real_gdp_growth(ctx, time_period=time_period)
        deflator_growth = baseline_gdp_deflator_growth(ctx, time_period=time_period)
        return xl_number(xl_number(xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(real_gdp_growth), xl_number(100.0)))) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(deflator_growth), xl_number(100.0))))) * xl_number(100.0)) - xl_number(100.0)
    return baseline_nominal_gdp_growth(ctx, time_period=time_period)


@xl_memoize
def hot_engine_overall_balance_pct_gdp_2(ctx: EvalContext, time_period: int) -> float:
    """Compute the overall government budget balance as a percentage of GDP for a given year.

Args:
    ctx: Workbook evaluation context.
    time_period (int): The year for which the balance is computed. Observed values
        range from 2030 to 2099.

Returns:
    float: Overall government budget balance as a percentage of GDP.

Note:
    Covers Hot!Y22:CP22. Excel: =Hot!AA17-Hot!AA18.
"""
    revenue_pct_gdp = hot_engine_revenue_pct_gdp(ctx, time_period=time_period)
    expenditure_pct_gdp = hot_engine_indicators_2(ctx, indicator='total_expenditure_pct_gdp', time_period=time_period)
    return xl_number(revenue_pct_gdp) - xl_number(expenditure_pct_gdp)


@xl_memoize
def hot_engine_primary_balance_lcu(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Compute the primary balance for the Hot engine scenario.

Args:
    ctx: Workbook evaluation context.
    time_period: Projection year, observed range 2009–2099.

Returns:
    Primary balance in LCU billions (float).

Note:
    Covers Hot!D28:CP28. Excel: =Hot!AA24-Hot!AA27.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        hot_revenue_lcu = hot_engine_revenue_lcu_2(ctx, time_period=time_period)
        hot_primary_expenditure_lcu = hot_engine_primary_expenditure_lcu(ctx, time_period=time_period)
        return xl_number(hot_revenue_lcu) - xl_number(hot_primary_expenditure_lcu)
    return baseline_engine_primary_balance_lcu(ctx, time_period=time_period)


@xl_memoize
def hot_engine_overall_balance_lcu(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Compute the overall engine balance for the Hot scenario in local currency units.

Args:
    ctx: Workbook evaluation context.
    time_period: The year for which to compute the balance (2009-2099).

Returns:
    The overall balance in local currency units.

Note:
    Covers Hot!D29:CP29. Excel: =Hot!AA24-Hot!AA25.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        revenue = hot_engine_revenue_lcu_2(ctx, time_period=time_period)
