@xl_memoize
def scenario_debt_stabilizing_primary_balance_hot(ctx: EvalContext, time_period: int) -> float:
    """Compute the debt stabilizing primary balance for the HOT scenario.

Args:
    ctx: The workbook evaluation context.
    time_period (int): The time period, ranging from 2009 to 2099.

Returns:
    float: The stabilizing primary balance as percent of GDP, or an Excel error for time_period 2009.

Note:
    Covers Hot!D36:CP36. Excel: =((Hot!AA32-Hot!AA11)/100)/(1+Hot!AA11/100)*Hot!Z35.
"""
    if time_period in {2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        projection_weighted_interest_rate = hot_engine_weighted_interest_rate(ctx, time_period=time_period)
        projection_nominal_gdp_growth = scenario_nominal_gdp_growth_hot(ctx, time_period=time_period)
        projection_nominal_gdp_growth_dup = scenario_nominal_gdp_growth_hot(ctx, time_period=time_period)
        projection_debt_to_gdp_prev = hot_engine_indicators_2(ctx, indicator='gross_debt_pct_gdp', time_period=time_period - 1)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(projection_weighted_interest_rate) - xl_number(projection_nominal_gdp_growth)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(projection_nominal_gdp_growth_dup), xl_number(100.0)))))) * xl_number(projection_debt_to_gdp_prev)
    if time_period in {2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025, 2026, 2027, 2028, 2029, 2030}:
        historical_weighted_interest_rate = hot_engine_weighted_interest_rate(ctx, time_period=time_period)
        historical_nominal_gdp_growth = scenario_nominal_gdp_growth_hot(ctx, time_period=time_period)
        historical_nominal_gdp_growth_dup = scenario_nominal_gdp_growth_hot(ctx, time_period=time_period)
        historical_debt_to_gdp_prev = hot_engine_indicators(ctx, indicator='gross_debt_pct_gdp', time_period=time_period - 1)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(historical_weighted_interest_rate) - xl_number(historical_nominal_gdp_growth)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(historical_nominal_gdp_growth_dup), xl_number(100.0)))))) * xl_number(historical_debt_to_gdp_prev)
    initial_weighted_interest_rate = hot_engine_weighted_interest_rate(ctx, time_period=2009)
    initial_nominal_gdp_growth = scenario_nominal_gdp_growth_hot(ctx, time_period=2009)
    initial_nominal_gdp_growth_dup = scenario_nominal_gdp_growth_hot(ctx, time_period=2009)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(initial_weighted_interest_rate) - xl_number(initial_nominal_gdp_growth)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(initial_nominal_gdp_growth_dup), xl_number(100.0)))))) * xl_number(xl_raise(XlError.REF))


@xl_memoize
def hot_engine_interest_expenditure_pct_revenue(ctx: EvalContext, time_period: int) -> float:
    """Compute interest expenditure as a percentage of revenue for a given time period.

Args:
    ctx: Workbook evaluation context.
    time_period: The time period (int). Observed range: 2009-2099.

Returns:
    float: Interest expenditure percentage of revenue. May raise DIV/0 if revenue is zero.

Note:
    Covers Hot!D37:CP37. Excel: =Hot!AA26/Hot!AA24*100.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        projected_interest_expenditure = hot_engine_indicators_2(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
        projected_revenue = hot_engine_revenue_lcu_2(ctx, time_period=time_period)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(projected_interest_expenditure), xl_number(projected_revenue))) * xl_number(100.0)
    historical_interest_expenditure = hot_engine_indicators(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
    historical_revenue = hot_engine_revenue_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(historical_interest_expenditure), xl_number(historical_revenue))) * xl_number(100.0)


@xl_memoize
def moderate_engine_revenue_pct_gdp(ctx: EvalContext, time_period: int) -> float:
    """Computes moderate scenario engine revenue as a percentage of GDP for a given time period.

Args:
    ctx: Workbook evaluation context.
    time_period (int): Projection year, observed in range 2009..2099.

Returns:
    float: Revenue as percent of GDP.

Note:
    Covers Moderate!D17:CP17. Excel: =Baseline!AA18+Moderate!AA40.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        baseline_rev_pct_gdp = baseline_revenue_pct_gdp_2(ctx, time_period=time_period)
        shock_rev_pct_gdp = moderate_engine_discrete_risk_revenue_shock(ctx, time_period=time_period)
        return xl_number(baseline_rev_pct_gdp) + xl_number(shock_rev_pct_gdp)
