@xl_memoize
def hot_engine_revenue_lcu_2(ctx: EvalContext, time_period: int) -> float:
    """Compute revenue in local currency units (LCU) by multiplying the revenue percentage of GDP with the nominal GDP in LCU.

Args:
    ctx: Workbook evaluation context.
    time_period (int): The time period for projection. Observed range: 2030 to 2099.

Returns:
    float: The revenue value in local currency units.

Note:
    Covers Hot!Y24:CP24. Excel: =Hot!AA17/100*Hot!AA13.
"""
    revenue_pct_gdp = hot_engine_revenue_pct_gdp(ctx, time_period=time_period)
    nominal_gdp_lcu = hot_engine_nominal_gdp_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(revenue_pct_gdp), xl_number(100.0))) * xl_number(nominal_gdp_lcu)


@xl_memoize
def hot_engine_primary_expenditure_lcu(ctx: EvalContext, time_period: int) -> int | float | CellValue:
    """Compute Hot scenario primary expenditure in local currency units (LCU) for a given time period.

Args:
    ctx: Workbook evaluation context.
    time_period: Integer year, observed from 2009 to 2099.

Returns:
    float: Primary expenditure in LCU for the Hot scenario.

Note:
    Covers Hot!D27:CP27. Excel: =Baseline!AA28-(1-Dashboard!C38)*(Baseline!AA28-(Hot!AA44/100*Hot!AA13))+Hot!AA41/100*Hot!AA13.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        baseline_expenditure = baseline_engine_indicators_3(ctx, indicator='primary_expenditure_lcu', time_period=time_period)
        expenditure_rigidity = read_expenditure_rigidity(ctx)
        baseline_expenditure_dup = baseline_engine_indicators_3(ctx, indicator='primary_expenditure_lcu', time_period=time_period)
        primary_expenditure_pct_gdp = hot_engine_memo_primary_expenditure_pct_gdp(ctx, time_period=time_period)
        nominal_gdp_lcu = hot_engine_nominal_gdp_lcu(ctx, time_period=time_period)
        expenditure_shock = hot_engine_discrete_risk_expenditure_shock(ctx, time_period=time_period)
        nominal_gdp_lcu_dup = hot_engine_nominal_gdp_lcu(ctx, time_period=time_period)
        return xl_number(xl_number(baseline_expenditure) - xl_number(xl_number(xl_number(1.0) - xl_number(expenditure_rigidity)) * xl_number(xl_number(baseline_expenditure_dup) - xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(primary_expenditure_pct_gdp), xl_number(100.0))) * xl_number(nominal_gdp_lcu))))) + xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(expenditure_shock), xl_number(100.0))) * xl_number(nominal_gdp_lcu_dup))
    return baseline_engine_indicators(ctx, indicator='primary_expenditure_lcu', time_period=time_period)


@xl_memoize
def hot_engine_nominal_gdp_lcu(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Compute nominal GDP in local currency units for the Hot engine scenario.

Args:
    ctx: Workbook evaluation context.
    time_period (int): Projection year, ranging from 2009 to 2099.

Returns:
    float: The computed nominal GDP in LCU for the given year.

Note:
    Covers Hot!D13:CP13. Excel: =Hot!Z13*(1+Hot!AA11/100).
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        prior_nominal_gdp_lcu = hot_engine_nominal_gdp_lcu(ctx, time_period=time_period - 1)
        nominal_growth_percent = scenario_nominal_gdp_growth_hot(ctx, time_period=time_period)
        return xl_number(prior_nominal_gdp_lcu) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(nominal_growth_percent), xl_number(100.0))))
    return macrofiscal_nominal_gdp_lcu(ctx, time_period=time_period)


@xl_memoize
def scenario_real_gdp_level_index_hot(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Compute the scenario real GDP level index (hot).

Args:
    time_period (int): Projection year, observed range 2009..2099.

Returns:
    float: Real GDP level index for the given year.

Note:
    Covers Hot!D14:CP14. Excel: =Hot!Z14*(1+Hot!AA9/100).
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        previous_index = scenario_real_gdp_level_index_hot(ctx, time_period=time_period - 1)
        growth_rate = hot_engine_real_gdp_growth(ctx, time_period=time_period)
        return xl_number(previous_index) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(growth_rate), xl_number(100.0))))
    return macrofiscal_real_gdp_lcu(ctx, time_period=time_period)


@xl_memoize
def scenario_nominal_gdp_growth_hot(ctx: EvalContext, time_period: int) -> float:
    """Compute scenario nominal GDP growth for hot engine projections.

Args:
    ctx (EvalContext): Workbook evaluation context.
    time_period (int): Projection year. Observed range 2009-2099.

Returns:
    float: Nominal GDP growth as a percentage.

Note:
    Covers Hot!D11:CP11. Excel: =(1+Hot!AA9/100)*(1+Baseline!AA14/100)*100-100.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        real_growth = hot_engine_real_gdp_growth(ctx, time_period=time_period)
        deflator_growth = baseline_gdp_deflator_growth(ctx, time_period=time_period)
        return xl_number(xl_number(xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(real_growth), xl_number(100.0)))) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(deflator_growth), xl_number(100.0))))) * xl_number(100.0)) - xl_number(100.0)
    return baseline_nominal_gdp_growth(ctx, time_period=time_period)


@xl_memoize
def high_engine_overall_balance_pct_gdp_2(ctx: EvalContext, time_period: int) -> float:
    """Computes the overall fiscal balance as percent of GDP for the High scenario.

Args:
    ctx: Workbook evaluation context.
    time_period: The projection year (int, typically in range 2030..2099).

Returns:
    The overall balance (% of GDP) computed as revenue minus total expenditure.

Note:
    Covers High!Y22:CP22. Excel: =High!AA17-High!AA18.
"""
    revenue_pct_gdp = high_engine_revenue_pct_gdp(ctx, time_period=time_period)
    total_expenditure_pct_gdp = high_engine_indicators_2(ctx, indicator='total_expenditure_pct_gdp', time_period=time_period)
    return xl_number(revenue_pct_gdp) - xl_number(total_expenditure_pct_gdp)


@xl_memoize
def high_engine_primary_balance_lcu(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Compute the primary balance for the High scenario in LCU billions.

Args:
    ctx: Workbook evaluation context.
    time_period: Projection year (int, observed range 2009..2099).

Returns:
    float: Primary balance for the given time period in LCU billions.

Note:
    Covers High!D28:CP28. Excel: =High!AA24-High!AA27.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        high_engine_revenue = high_engine_revenue_lcu_2(ctx, time_period=time_period)
        high_engine_primary_expenditure = high_engine_primary_expenditure_lcu(ctx, time_period=time_period)
        return xl_number(high_engine_revenue) - xl_number(high_engine_primary_expenditure)
    return baseline_engine_primary_balance_lcu(ctx, time_period=time_period)


@xl_memoize
def high_engine_overall_balance_lcu(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Calculate High scenario overall balance in local currency units (LCU) for a given time period.

Args:
    ctx: Workbook evaluation context.
    time_period: Year as an integer (e.g., 2009, 2030).

Returns:
    Overall balance as a float.

Note:
    Covers High!D29:CP29. Excel: =High!AA24-High!AA25.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        revenue = high_engine_revenue_lcu_2(ctx, time_period=time_period)
        expenditure = high_engine_indicators_2(ctx, indicator='total_expenditure_lcu', time_period=time_period)
