@xl_memoize
def scenario_debt_stabilizing_primary_balance_high(ctx: EvalContext, time_period: int) -> float:
    """Computes the debt-stabilizing primary balance for the high scenario.

Args:
    ctx: Workbook evaluation context.
    time_period: The projection time period (2009..2099).

Returns:
    The computed primary balance (float), or raises an Excel error for 2009.

Note:
    Covers High!D36:CP36. Excel: =((High!AA32-High!AA11)/100)/(1+High!AA11/100)*High!Z35.
"""
    if time_period in {2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        future_interest_rate = high_engine_weighted_interest_rate(ctx, time_period=time_period)
        future_growth_rate_subtract = scenario_nominal_gdp_growth_high(ctx, time_period=time_period)
        future_growth_rate_denom = scenario_nominal_gdp_growth_high(ctx, time_period=time_period)
        future_previous_debt = high_engine_indicators_2(ctx, indicator='gross_debt_pct_gdp', time_period=time_period - 1)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(future_interest_rate) - xl_number(future_growth_rate_subtract)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(future_growth_rate_denom), xl_number(100.0)))))) * xl_number(future_previous_debt)
    if time_period in {2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025, 2026, 2027, 2028, 2029, 2030}:
        mid_interest_rate = high_engine_weighted_interest_rate(ctx, time_period=time_period)
        mid_growth_rate_subtract = scenario_nominal_gdp_growth_high(ctx, time_period=time_period)
        mid_growth_rate_denom = scenario_nominal_gdp_growth_high(ctx, time_period=time_period)
        mid_previous_debt = high_engine_indicators(ctx, indicator='gross_debt_pct_gdp', time_period=time_period - 1)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(mid_interest_rate) - xl_number(mid_growth_rate_subtract)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(mid_growth_rate_denom), xl_number(100.0)))))) * xl_number(mid_previous_debt)
    initial_interest_rate = high_engine_weighted_interest_rate(ctx, time_period=2009)
    initial_growth_rate_subtract = scenario_nominal_gdp_growth_high(ctx, time_period=2009)
    initial_growth_rate_denom = scenario_nominal_gdp_growth_high(ctx, time_period=2009)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(initial_interest_rate) - xl_number(initial_growth_rate_subtract)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(initial_growth_rate_denom), xl_number(100.0)))))) * xl_number(xl_raise(XlError.REF))


@xl_memoize
def high_engine_interest_expenditure_pct_revenue(ctx: EvalContext, time_period: int) -> float:
    """Compute interest expenditure as a percentage of revenue.

Args:
    time_period (int): The financial year, range 2009–2099.

Returns:
    float: Interest expenditure as a percentage of revenue.

Note:
    Covers High!D37:CP37. Excel: =High!AA26/High!AA24*100.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        interest_expenditure_projection = high_engine_indicators_2(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
        revenue_projection = high_engine_revenue_lcu_2(ctx, time_period=time_period)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(interest_expenditure_projection), xl_number(revenue_projection))) * xl_number(100.0)
    interest_expenditure_historical = high_engine_indicators(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
    revenue_historical = high_engine_revenue_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(interest_expenditure_historical), xl_number(revenue_historical))) * xl_number(100.0)


