@xl_memoize
def baseline_engine_interest_expenditure_pct_revenue(ctx: EvalContext, time_period: int) -> float:
    """Computes interest expenditure as a percentage of revenue.

Args:
    time_period (int): The projection year, in the range 2009-2099.

Returns:
    float: Interest expenditure divided by revenue, multiplied by 100. Returns #DIV/0! if revenue is zero.

Note:
    Covers Baseline!D38:CP38. Excel: =Baseline!AA27/Baseline!AA25*100.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        interest_expenditure = baseline_engine_indicators_3(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
        revenue = baseline_engine_revenue_lcu_2(ctx, time_period=time_period)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(interest_expenditure), xl_number(revenue))) * xl_number(100.0)
    early_interest_expenditure = baseline_engine_indicators(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
    early_revenue = baseline_engine_revenue_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(early_interest_expenditure), xl_number(early_revenue))) * xl_number(100.0)


