@xl_memoize
def high_engine_real_gdp_growth(ctx: EvalContext, time_period: int) -> float:
    """Calculate real GDP growth for the high scenario.

Args:
    ctx: Workbook evaluation context.
    time_period: Projection year, ranging from 2030 to 2099.

Returns:
    The computed real GDP growth rate in percent.

Note:
    Covers High!Y9:CP9. Excel: =(1+Baseline!AA11/100)*(1+(Baseline!AA12+'Climate Database'!T19)/100)*100-100.
"""
    employment_growth = baseline_employment_growth(ctx, time_period=time_period)
    labour_productivity_baseline = baseline_labour_productivity_growth(ctx, time_period=time_period)
    labour_productivity_climate_variation = climate_database_labour_productivity_growth_variation_high(ctx, time_period=time_period)
    return xl_number(xl_number(xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(employment_growth), xl_number(100.0)))) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(labour_productivity_baseline) + xl_number(labour_productivity_climate_variation)), xl_number(100.0))))) * xl_number(100.0)) - xl_number(100.0)


@xl_memoize
def output_scenarios_dspb_milestones_baseline(ctx: EvalContext, fiscal_measure: str, time_period: int) -> int | float | CellValue:
    """Compute a milestone value for the debt-stabilizing primary balance baseline output scenario.

Args:
    ctx: Workbook evaluation context.
    fiscal_measure: Fiscal measure identifier. One of {'PB', 'PB*', 'PB Gap'}.
    time_period: Projection year. One of {2023, 2050, 2075, 2099}.

Returns:
    The requested milestone value as a float. For 'PB', returns the primary 
    balance. For 'PB*', returns the debt-stabilizing primary balance 
    (using a fixed 2023 value for the first period). For 'PB Gap', returns 
    the difference between the debt-stabilizing primary balance and the 
    primary balance.

Note:
    Covers 'Output Scenarios'!C25:N25. Excel: ='Output Scenarios'!C5.
"""
    if fiscal_measure == 'PB':
        return output_scenarios_primary_balance_pct_gdp_summary_baseline(ctx, time_period=time_period)
    if (fiscal_measure, time_period) in {('PB*', 2023)}:
        return baseline_engine_indicators_2(ctx, indicator='debt_stabilizing_primary_balance', time_period=2023)
    if fiscal_measure == 'PB*':
        return baseline_engine_indicators_3(ctx, indicator='debt_stabilizing_primary_balance', time_period=time_period)
    debt_stabilizing_pb = output_scenarios_dspb_milestones_baseline(ctx, fiscal_measure='PB*', time_period=time_period)
    primary_balance = output_scenarios_dspb_milestones_baseline(ctx, fiscal_measure='PB', time_period=time_period)
    return xl_number(debt_stabilizing_pb) - xl_number(primary_balance)


@xl_memoize
def baseline_overall_balance_pct_gdp_2(ctx: EvalContext, time_period: int) -> float:
    """Calculate the overall fiscal balance as a percentage of GDP.

Args:
    ctx: Workbook evaluation context.
    time_period: Projection year (2030..2099).

Returns:
    Overall fiscal balance as a percentage of GDP.

Note:
    Covers Baseline!Y23:CP23. Excel: =Baseline!AA18-Baseline!AA19.
"""
    revenue_pct_gdp = baseline_revenue_pct_gdp_2(ctx, time_period=time_period)
    total_expenditure_pct_gdp = baseline_engine_indicators_3(ctx, indicator='total_expenditure_pct_gdp', time_period=time_period)
    return xl_number(revenue_pct_gdp) - xl_number(total_expenditure_pct_gdp)


