@xl_memoize
def output_scenarios_primary_balance_pct_gdp_summary_baseline(ctx: EvalContext, time_period: int) -> int | float | CellValue:
    """Retrieve the baseline primary balance as a percentage of GDP for a given projection year.

Args:
    ctx: The workbook evaluation context.
    time_period: The projection year (observed values: 2023, 2050, 2075, 2099).

Returns:
    The primary balance (% of GDP) for the baseline scenario.

Note:
    Covers 'Output Scenarios'!C5:F5. Excel: =Baseline!R22.
"""
    if time_period == 2023:
        return baseline_engine_indicators(ctx, indicator='primary_balance_pct_gdp', time_period=2023)
    return baseline_engine_indicators_3(ctx, indicator='primary_balance_pct_gdp', time_period=time_period)


@xl_memoize
def output_baseline_dspb_milestones(ctx: EvalContext, fiscal_measure: str, time_period: int) -> int | float | CellValue:
    """Return the debt-stabilizing primary balance (DSPB) milestone measure for a given fiscal measure and time period.

Args:
    ctx: Workbook evaluation context.
    fiscal_measure: The fiscal measure to retrieve, one of 'PB', 'PB*', 'PB Gap'.
    time_period: The projection time period (2023 or 2050).

Returns:
    The corresponding DSPB measure as a floating-point number.

Note:
    Covers 'Output Baseline'!C16:H16. Excel: ='Output Baseline'!C8.
"""
    if fiscal_measure == 'PB':
        return output_baseline_primary_balance_pct_gdp_summary(ctx, time_period=time_period)
    if (fiscal_measure, time_period) in {('PB*', 2023)}:
        return baseline_engine_indicators_2(ctx, indicator='debt_stabilizing_primary_balance', time_period=2023)
    if fiscal_measure == 'PB*':
        return baseline_engine_indicators_3(ctx, indicator='debt_stabilizing_primary_balance', time_period=2050)
    dspb_pb_star = output_baseline_dspb_milestones(ctx, fiscal_measure='PB*', time_period=time_period)
    dspb_pb = output_baseline_dspb_milestones(ctx, fiscal_measure='PB', time_period=time_period)
    return xl_number(dspb_pb_star) - xl_number(dspb_pb)


