@xl_memoize
def scenario_debt_stabilizing_primary_balance_hot_unadapted(ctx: EvalContext, time_period: int) -> float:
    """Computes the debt-stabilizing primary balance (as percent of GDP) using the formula (r - g) / (1 + g) * d_{t-1}, where r is the weighted average interest rate, g is the nominal GDP growth rate, and d_{t-1} is the prior-year gross debt-to-GDP ratio. The calculation uses different engine indicator versions for different time periods: from 2031 onward, version 2 indicators; from 2010 to 2030, version 1; for the base year 2009, the prior debt ratio is missing, resulting in a #REF! error.

Args:
    ctx: Workbook evaluation context.
    time_period: The year for which the primary balance is calculated. Valid range: 2009 to 2099.

Returns:
    The debt-stabilizing primary balance as a float. Returns an error for time_period 2009.

Note:
    Covers 'Hot Unadapted'!D36:CP36. Excel: =(('Hot Unadapted'!AA32-'Hot Unadapted'!AA11)/100)/(1+'Hot Unadapted'!AA11/100)*'Hot Unadapted'!Z35.
"""
    if time_period in {2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        weighted_interest_rate_v2 = hot_unadapted_engine_weighted_interest_rate(ctx, time_period=time_period)
        nominal_gdp_growth_v2_numerator = scenario_nominal_gdp_growth_hot_unadapted(ctx, time_period=time_period)
        nominal_gdp_growth_v2_denominator = scenario_nominal_gdp_growth_hot_unadapted(ctx, time_period=time_period)
        prior_gross_debt_pct_gdp_v2 = hot_unadapted_engine_indicators_2(ctx, indicator='gross_debt_pct_gdp', time_period=time_period - 1)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(weighted_interest_rate_v2) - xl_number(nominal_gdp_growth_v2_numerator)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(nominal_gdp_growth_v2_denominator), xl_number(100.0)))))) * xl_number(prior_gross_debt_pct_gdp_v2)
    if time_period in {2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025, 2026, 2027, 2028, 2029, 2030}:
        weighted_interest_rate_v1 = hot_unadapted_engine_weighted_interest_rate(ctx, time_period=time_period)
        nominal_gdp_growth_v1_numerator = scenario_nominal_gdp_growth_hot_unadapted(ctx, time_period=time_period)
        nominal_gdp_growth_v1_denominator = scenario_nominal_gdp_growth_hot_unadapted(ctx, time_period=time_period)
        prior_gross_debt_pct_gdp_v1 = hot_unadapted_engine_indicators(ctx, indicator='gross_debt_pct_gdp', time_period=time_period - 1)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(weighted_interest_rate_v1) - xl_number(nominal_gdp_growth_v1_numerator)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(nominal_gdp_growth_v1_denominator), xl_number(100.0)))))) * xl_number(prior_gross_debt_pct_gdp_v1)
    base_weighted_interest_rate = hot_unadapted_engine_weighted_interest_rate(ctx, time_period=2009)
    base_nominal_gdp_growth_numerator = scenario_nominal_gdp_growth_hot_unadapted(ctx, time_period=2009)
    base_nominal_gdp_growth_denominator = scenario_nominal_gdp_growth_hot_unadapted(ctx, time_period=2009)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(base_weighted_interest_rate) - xl_number(base_nominal_gdp_growth_numerator)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(base_nominal_gdp_growth_denominator), xl_number(100.0)))))) * xl_number(xl_raise(XlError.REF))


@xl_memoize
def hot_unadapted_engine_interest_expenditure_pct_revenue(ctx: EvalContext, time_period: int) -> float:
    """Computes the Hot Unadapted engine interest expenditure as a percentage of revenue for a given time period.

Args:
    ctx: The workbook evaluation context.
    time_period: The time period (year) for which to compute the metric. Observed range: 2009..2099.

Returns:
    The interest expenditure as a percentage of revenue.

Note:
    Covers 'Hot Unadapted'!D37:CP37. Excel: ='Hot Unadapted'!AA26/'Hot Unadapted'!AA24*100.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        extended_interest_expenditure_lcu = hot_unadapted_engine_indicators_2(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
        extended_revenue_lcu = hot_unadapted_engine_revenue_lcu_2(ctx, time_period=time_period)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(extended_interest_expenditure_lcu), xl_number(extended_revenue_lcu))) * xl_number(100.0)
    base_interest_expenditure_lcu = hot_unadapted_engine_indicators(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
    base_revenue_lcu = hot_unadapted_engine_revenue_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(base_interest_expenditure_lcu), xl_number(base_revenue_lcu))) * xl_number(100.0)


