@xl_memoize
def scenario_debt_stabilizing_primary_balance_hot_adapted(ctx: EvalContext, time_period: int) -> float:
    """Calculate the contribution of the interest rate-growth differential to the debt-to-GDP ratio.

Args:
    ctx: Workbook evaluation context.
    time_period: The projection year (integer). Must be between 2009 and 2099.

Returns:
    The contribution to the debt-to-GDP ratio from the interest rate-growth
    differential, or an Excel #REF! error for time_period=2009.

Note:
    Covers 'Hot Adapted'!D36:CP36. Excel: =(('Hot Adapted'!AA32-'Hot Adapted'!AA11)/100)/(1+'Hot Adapted'!AA11/100)*'Hot Adapted'!Z35.
"""
    if time_period in {2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        f1_interest_rate = hot_adapted_engine_weighted_interest_rate(ctx, time_period=time_period)
        f1_nominal_gdp_growth_1 = scenario_nominal_gdp_growth_hot_adapted(ctx, time_period=time_period)
        f1_nominal_gdp_growth_2 = scenario_nominal_gdp_growth_hot_adapted(ctx, time_period=time_period)
        f1_lagged_debt_ratio = hot_adapted_engine_indicators_2(ctx, indicator='gross_debt_pct_gdp', time_period=time_period - 1)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(f1_interest_rate) - xl_number(f1_nominal_gdp_growth_1)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(f1_nominal_gdp_growth_2), xl_number(100.0)))))) * xl_number(f1_lagged_debt_ratio)
    if time_period in {2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025, 2026, 2027, 2028, 2029, 2030}:
        f2_interest_rate = hot_adapted_engine_weighted_interest_rate(ctx, time_period=time_period)
        f2_nominal_gdp_growth_1 = scenario_nominal_gdp_growth_hot_adapted(ctx, time_period=time_period)
        f2_nominal_gdp_growth_2 = scenario_nominal_gdp_growth_hot_adapted(ctx, time_period=time_period)
        f2_lagged_debt_ratio = hot_adapted_engine_indicators(ctx, indicator='gross_debt_pct_gdp', time_period=time_period - 1)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(f2_interest_rate) - xl_number(f2_nominal_gdp_growth_1)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(f2_nominal_gdp_growth_2), xl_number(100.0)))))) * xl_number(f2_lagged_debt_ratio)
    f3_interest_rate = hot_adapted_engine_weighted_interest_rate(ctx, time_period=2009)
    f3_nominal_gdp_growth_1 = scenario_nominal_gdp_growth_hot_adapted(ctx, time_period=2009)
    f3_nominal_gdp_growth_2 = scenario_nominal_gdp_growth_hot_adapted(ctx, time_period=2009)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(f3_interest_rate) - xl_number(f3_nominal_gdp_growth_1)), xl_number(100.0))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(f3_nominal_gdp_growth_2), xl_number(100.0)))))) * xl_number(xl_raise(XlError.REF))


@xl_memoize
def hot_adapted_engine_interest_expenditure_pct_revenue(ctx: EvalContext, time_period: int) -> float:
    """Calculate interest expenditure as a percentage of revenue for the hot adapted engine.

Args:
    ctx: Workbook evaluation context.
    time_period: The projection year, an integer between 2009 and 2099.

Returns:
    Interest expenditure as a percentage of revenue (float). Returns a division error if revenue is zero.

Note:
    Covers 'Hot Adapted'!D37:CP37. Excel: ='Hot Adapted'!AA26/'Hot Adapted'!AA24*100.
"""
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099}:
        late_interest_expenditure = hot_adapted_engine_indicators_2(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
        late_revenue = hot_adapted_engine_revenue_lcu_2(ctx, time_period=time_period)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(late_interest_expenditure), xl_number(late_revenue))) * xl_number(100.0)
    early_interest_expenditure = hot_adapted_engine_indicators(ctx, indicator='interest_expenditure_lcu', time_period=time_period)
    early_revenue = hot_adapted_engine_revenue_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(early_interest_expenditure), xl_number(early_revenue))) * xl_number(100.0)


