@xl_memoize
def baseline_employment_growth(ctx: EvalContext, time_period: int) -> float:
    """Computes the year-over-year percentage growth of the working age population, serving as a baseline employment growth projection.

Args:
    time_period: The projection year (int, observed range 2022..2099).

Returns:
    The percentage growth rate (float).

Note:
    Covers Baseline!Q11:CP11. Excel: =Demography!CG3/Demography!CF3*100-100.
"""
    if time_period in {2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021}:
        return baseline_employment_growth_2(ctx, time_period=time_period)
    current_population = demography_working_age_population(ctx, time_period=time_period)
    previous_population = demography_working_age_population(ctx, time_period=time_period - 1)
    return xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(current_population), xl_number(previous_population))) * xl_number(100.0)) - xl_number(100.0)


@xl_memoize
def productivity_growth(ctx: EvalContext, time_period: int) -> float:
    """Compute the labour productivity growth rate (percent) for a given year.

Args:
    ctx (EvalContext): Evaluation context providing access to workbook data.
    time_period (int): The year for which productivity growth is computed. Typical
        values include 2009–2022, 2030–2099.

Returns:
    float: The labour productivity growth rate in percent.

Note:
    Covers Productivity!AE6, Productivity!AF6, Productivity!AG6, Productivity!AH6, Productivity!AI6, Productivity!AJ6, Productivity!AK6, Productivity!AL6, Productivity!AM6, Productivity!AN6, Productivity!AO6, Productivity!AP6, Productivity!AQ6, Productivity!AR6, Productivity!AS6, Productivity!AT6, Productivity!AU6, Productivity!AV6, Productivity!AW6, Productivity!AX6, Productivity!AY6, Productivity!AZ6, Productivity!BA6, Productivity!BB6, Productivity!BC6, Productivity!BD6, Productivity!BE6, Productivity!BF6, Productivity!BG6, Productivity!BH6, Productivity!BI6, Productivity!BJ6, Productivity!BK6, Productivity!BL6, Productivity!BM6, Productivity!BN6, Productivity!BO6, Productivity!BP6, Productivity!BQ6, Productivity!BR6, Productivity!BS6, Productivity!BT6, Productivity!BU6, Productivity!BV6, Productivity!BW6, Productivity!BX6, Productivity!BY6, Productivity!BZ6, Productivity!CA6, Productivity!CB6, Productivity!CC6, Productivity!CD6, Productivity!CE6, Productivity!CF6, Productivity!CG6, Productivity!CH6, Productivity!CI6, Productivity!CJ6, Productivity!CK6, Productivity!CL6, Productivity!CM6, Productivity!CN6, Productivity!CO6, Productivity!CP6, Productivity!CQ6, Productivity!CR6, Productivity!CS6, Productivity!CT6, Productivity!CU6, Productivity!CV6, Productivity!J6, Productivity!K6, Productivity!L6, Productivity!M6, Productivity!N6, Productivity!O6, Productivity!P6, Productivity!Q6, Productivity!R6, Productivity!S6, Productivity!T6, Productivity!U6, Productivity!V6, Productivity!W6. Excel: =Productivity!AE3/Productivity!AD3*100-100.
"""
    if time_period in {2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098}:
        current_level = productivity_level(ctx, time_period=time_period)
        previous_level = productivity_level(ctx, time_period=time_period - 1)
        return xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(current_level), xl_number(previous_level))) * xl_number(100.0)) - xl_number(100.0)
    prod_2098_num = productivity_level(ctx, time_period=2098)
    start_rate = read_productivity_start(ctx)
    end_rate = read_productivity_end(ctx)
    start_rate_dup = read_productivity_start(ctx)
    steepness = read_productivity_convergence_logistic_steepness(ctx)
    period_index_2070 = read_productivity_convergence_period_index(ctx, time_period=2070)
    midpoint = read_productivity_convergence_logistic_midpoint(ctx)
    exp_factor = xl_exp(xl_number(-xl_number(steepness)) * xl_number(xl_number(period_index_2070) - xl_number(midpoint)))
    steepness_exponent = read_productivity_convergence_logistic_steepness(ctx)
    prod_2098_den = productivity_level(ctx, time_period=2098)
    return xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(prod_2098_num) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(start_rate) + xl_number(xl_number(xl_number(end_rate) - xl_number(start_rate_dup)) * xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(1.0), xl_number(xl_pow_numbers(xl_number(xl_number(1.0) + xl_number(exp_factor)), xl_number(steepness_exponent))))))), xl_number(100.0))))), xl_number(prod_2098_den))) * xl_number(100.0)) - xl_number(100.0)


@xl_memoize
def baseline_engine_indicators(ctx: EvalContext, indicator: str, time_period: int) -> int | float | CellValue:
    """Compute a baseline fiscal indicator for a given projection year.

Args:
    ctx: Workbook evaluation context.
    indicator: One of 'debt_trajectory_direction', 'gross_debt_lcu', 'gross_debt_pct_gdp', 'interest_expenditure_lcu', 'interest_expenditure_pct_gdp', 'primary_balance_pct_gdp', 'primary_expenditure_lcu', 'primary_expenditure_pct_gdp', 'total_expenditure_lcu', 'total_expenditure_pct_gdp'.
    time_period: Projection year (2009..2029).

Returns:
    Numeric indicator value. For ratio indicators the value is expressed as a percentage (0-100+).

Note:
    Covers Baseline!D19, Baseline!D20, Baseline!D21, Baseline!D22, Baseline!D26, Baseline!D27, Baseline!D28, Baseline!D35, Baseline!D36, Baseline!E19, Baseline!E20, Baseline!E21, Baseline!E22, Baseline!E26, Baseline!E27, Baseline!E28, Baseline!E35, Baseline!E36, Baseline!F19, Baseline!F20, Baseline!F21, Baseline!F22, Baseline!F26, Baseline!F27, Baseline!F28, Baseline!F35, Baseline!F36, Baseline!G19, Baseline!G20, Baseline!G21, Baseline!G22, Baseline!G26, Baseline!G27, Baseline!G28, Baseline!G35, Baseline!G36, Baseline!H19, Baseline!H20, Baseline!H21, Baseline!H22, Baseline!H26, Baseline!H27, Baseline!H28, Baseline!H35, Baseline!H36, Baseline!I19, Baseline!I20, Baseline!I21, Baseline!I22, Baseline!I26, Baseline!I27, Baseline!I28, Baseline!I35, Baseline!I36, Baseline!J19, Baseline!J20, Baseline!J21, Baseline!J22, Baseline!J26, Baseline!J27, Baseline!J28, Baseline!J35, Baseline!J36, Baseline!K19, Baseline!K20, Baseline!K21, Baseline!K22, Baseline!K26, Baseline!K27, Baseline!K28, Baseline!K35, Baseline!K36, Baseline!L19, Baseline!L20, Baseline!L21, Baseline!L22, Baseline!L26, Baseline!L27, Baseline!L28, Baseline!L35, Baseline!L36, Baseline!M19, Baseline!M20, Baseline!M21, Baseline!M22, Baseline!M26, Baseline!M27, Baseline!M28, Baseline!M35, Baseline!M36, Baseline!N19, Baseline!N20, Baseline!N21, Baseline!N22, Baseline!N26, Baseline!N27, Baseline!N28, Baseline!N35, Baseline!N36, Baseline!O19, Baseline!O20, Baseline!O21, Baseline!O22, Baseline!O26, Baseline!O27, Baseline!O28, Baseline!O35, Baseline!O36, Baseline!P19, Baseline!P20, Baseline!P21, Baseline!P22, Baseline!P26, Baseline!P27, Baseline!P28, Baseline!P35, Baseline!P36, Baseline!Q19, Baseline!Q20, Baseline!Q21, Baseline!Q22, Baseline!Q26, Baseline!Q27, Baseline!Q28, Baseline!Q35, Baseline!Q36, Baseline!R19, Baseline!R20, Baseline!R21, Baseline!R22, Baseline!R26, Baseline!R27, Baseline!R28, Baseline!R35, Baseline!R36, Baseline!S19, Baseline!S20, Baseline!S21, Baseline!S22, Baseline!S26, Baseline!S27, Baseline!S28, Baseline!S35, Baseline!S36, Baseline!T19, Baseline!T20, Baseline!T21, Baseline!T22, Baseline!T26, Baseline!T27, Baseline!T28, Baseline!T35, Baseline!T36, Baseline!U19, Baseline!U20, Baseline!U21, Baseline!U22, Baseline!U26, Baseline!U27, Baseline!U28, Baseline!U35, Baseline!U36, Baseline!V19, Baseline!V20, Baseline!V21, Baseline!V22, Baseline!V26, Baseline!V27, Baseline!V28, Baseline!V35, Baseline!V36, Baseline!W19, Baseline!W20, Baseline!W21, Baseline!W22, Baseline!W26, Baseline!W27, Baseline!W28, Baseline!W35, Baseline!W36, Baseline!X19, Baseline!X20, Baseline!X21, Baseline!X22, Baseline!X26, Baseline!X27, Baseline!X28, Baseline!X35, Baseline!X36, Baseline!X46. Excel: =Baseline!AA26/Baseline!AA8*100.
"""
    if indicator in {'interest_expenditure_pct_gdp', 'total_expenditure_pct_gdp'}:
        lcu_indicator_lookup = {'interest_expenditure_pct_gdp': 'interest_expenditure_lcu', 'total_expenditure_pct_gdp': 'total_expenditure_lcu'}
        lcu_value = baseline_engine_indicators(ctx, indicator=lcu_indicator_lookup[indicator], time_period=time_period)
        nominal_gdp = macrofiscal_nominal_gdp_lcu(ctx, time_period=time_period)
        return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(lcu_value), xl_number(nominal_gdp))) * xl_number(100.0)
    if indicator == 'primary_expenditure_pct_gdp':
        return macrofiscal_primary_expenditure_pct_gdp(ctx, time_period=time_period)
    if indicator == 'primary_balance_pct_gdp':
        return macrofiscal_primary_balance_pct_gdp(ctx, time_period=time_period)
    if indicator == 'total_expenditure_lcu':
        return macrofiscal_expenditure_lcu(ctx, time_period=time_period)
    if indicator == 'interest_expenditure_lcu':
        return macrofiscal_interest_expenditure_lcu(ctx, time_period=time_period)
    if indicator == 'primary_expenditure_lcu':
        return macrofiscal_primary_expenditure_lcu(ctx, time_period=time_period)
    if indicator == 'gross_debt_lcu':
        return macrofiscal_debt_lcu(ctx, time_period=time_period)
    if indicator == 'gross_debt_pct_gdp':
        return macrofiscal_debt_to_gdp(ctx, time_period=time_period)
    debt_gdp_end = baseline_engine_indicators(ctx, indicator='gross_debt_pct_gdp', time_period=2029)
    debt_gdp_prev = baseline_engine_indicators(ctx, indicator='gross_debt_pct_gdp', time_period=2028)
    return 1.0 if (is_increasing := xl_bool(xl_compare('>', debt_gdp_end, debt_gdp_prev))) else 2.0 if (is_decreasing := xl_bool(xl_compare('<', baseline_engine_indicators(ctx, indicator='gross_debt_pct_gdp', time_period=2029), baseline_engine_indicators(ctx, indicator='gross_debt_pct_gdp', time_period=2028)))) else 0


