@xl_memoize
def productivity_level(ctx: EvalContext, time_period: int) -> float | CellValue:
    """Compute labour productivity level for a given year.

Args:
    time_period: The year for which to compute the productivity level. 
        Observed values: 2008-2022, 2025, 2029, and 2030-2098.

Returns:
    float: The labour productivity level for the given year in USD PPP.

Note:
    Covers Productivity!AD3, Productivity!AE3, Productivity!AF3, Productivity!AG3, Productivity!AH3, Productivity!AI3, Productivity!AJ3, Productivity!AK3, Productivity!AL3, Productivity!AM3, Productivity!AN3, Productivity!AO3, Productivity!AP3, Productivity!AQ3, Productivity!AR3, Productivity!AS3, Productivity!AT3, Productivity!AU3, Productivity!AV3, Productivity!AW3, Productivity!AX3, Productivity!AY3, Productivity!AZ3, Productivity!BA3, Productivity!BB3, Productivity!BC3, Productivity!BD3, Productivity!BE3, Productivity!BF3, Productivity!BG3, Productivity!BH3, Productivity!BI3, Productivity!BJ3, Productivity!BK3, Productivity!BL3, Productivity!BM3, Productivity!BN3, Productivity!BO3, Productivity!BP3, Productivity!BQ3, Productivity!BR3, Productivity!BS3, Productivity!BT3, Productivity!BU3, Productivity!BV3, Productivity!BW3, Productivity!BX3, Productivity!BY3, Productivity!BZ3, Productivity!CA3, Productivity!CB3, Productivity!CC3, Productivity!CD3, Productivity!CE3, Productivity!CF3, Productivity!CG3, Productivity!CH3, Productivity!CI3, Productivity!CJ3, Productivity!CK3, Productivity!CL3, Productivity!CM3, Productivity!CN3, Productivity!CO3, Productivity!CP3, Productivity!CQ3, Productivity!CR3, Productivity!CS3, Productivity!CT3, Productivity!CU3, Productivity!I3, Productivity!J3, Productivity!K3, Productivity!L3, Productivity!M3, Productivity!N3, Productivity!O3, Productivity!P3, Productivity!Q3, Productivity!R3, Productivity!S3, Productivity!T3, Productivity!U3, Productivity!V3, Productivity!W3, Productivity!Z3. Excel: =(((Productivity!Z3*(1+Dashboard!C20/100))*(1+Dashboard!C20/100))*(1+Dashboard!C20/100))*(1+Dashboard!C20/100).
"""
    if time_period == 2029:
        productivity_level_2025 = productivity_level(ctx, time_period=2025)
        start_growth_rate_f1_1 = read_productivity_start(ctx)
        start_growth_rate_f1_2 = read_productivity_start(ctx)
        start_growth_rate_f1_3 = read_productivity_start(ctx)
        start_growth_rate_f1_4 = read_productivity_start(ctx)
        return xl_number(xl_number(xl_number(xl_number(productivity_level_2025) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(start_growth_rate_f1_1), xl_number(100.0))))) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(start_growth_rate_f1_2), xl_number(100.0))))) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(start_growth_rate_f1_3), xl_number(100.0))))) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(start_growth_rate_f1_4), xl_number(100.0))))
    if time_period in {2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098}:
        previous_productivity_level = productivity_level(ctx, time_period=time_period - 1)
        start_growth_rate_f2_1 = read_productivity_start(ctx)
        end_growth_rate = read_productivity_end(ctx)
        start_growth_rate_f2_2 = read_productivity_start(ctx)
        steepness_f2_1 = read_productivity_convergence_logistic_steepness(ctx)
        period_index = read_productivity_convergence_period_index(ctx, time_period=time_period - 29)
        midpoint = read_productivity_convergence_logistic_midpoint(ctx)
        exponential_argument = xl_exp(xl_number(-xl_number(steepness_f2_1)) * xl_number(xl_number(period_index) - xl_number(midpoint)))
        steepness_f2_2 = read_productivity_convergence_logistic_steepness(ctx)
        return xl_number(previous_productivity_level) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(start_growth_rate_f2_1) + xl_number(xl_number(xl_number(end_growth_rate) - xl_number(start_growth_rate_f2_2)) * xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(1.0), xl_number(xl_pow_numbers(xl_number(xl_number(1.0) + xl_number(exponential_argument)), xl_number(steepness_f2_2))))))), xl_number(100.0))))
    if time_period in {2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022}:
        historical_productivity_start_column = {2008: 19, 2009: 20, 2010: 21, 2011: 22, 2012: 23, 2013: 24, 2014: 25, 2015: 26, 2016: 27, 2017: 28, 2018: 29, 2019: 30, 2020: 31, 2021: 32, 2022: 33}
        historical_productivity_end_column = {2008: 49, 2009: 50, 2010: 51, 2011: 52, 2012: 53, 2013: 54, 2014: 55, 2015: 56, 2016: 57, 2017: 58, 2018: 59, 2019: 60, 2020: 61, 2021: 62, 2022: 63}
        country_name = read_country(ctx)
        country_column_range = xl_range(ctx, 'Productivity!A63:A260')
        row_index = xl_match(country_name, country_column_range, 0.0)
        return xl_offset(ctx, xl_index_ref(('Productivity', 63, historical_productivity_start_column[time_period], 260, historical_productivity_end_column[time_period]), row_index, 1.0), 0.0, 0.0)
    productivity_level_2022 = productivity_level(ctx, time_period=2022)
    start_growth_rate_f4_1 = read_productivity_start(ctx)
    start_growth_rate_f4_2 = read_productivity_start(ctx)
    start_growth_rate_f4_3 = read_productivity_start(ctx)
    return xl_number(xl_number(xl_number(productivity_level_2022) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(start_growth_rate_f4_1), xl_number(100.0))))) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(start_growth_rate_f4_2), xl_number(100.0))))) * xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(start_growth_rate_f4_3), xl_number(100.0))))


@xl_memoize
def macrofiscal_primary_expenditure_pct_gdp(ctx: EvalContext, time_period: int) -> float:
    """Compute primary expenditure as a percentage of nominal GDP for a given time period.

Args:
    time_period: Projection year (observed range 2009..2029).

Returns:
    Primary expenditure as a percentage of GDP.

Note:
    Covers Macrofiscal!K17:AE17. Excel: =Macrofiscal!AA12/Macrofiscal!AA4*100.
"""
    primary_expenditure = macrofiscal_primary_expenditure_lcu(ctx, time_period=time_period)
    nominal_gdp = macrofiscal_nominal_gdp_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(primary_expenditure), xl_number(nominal_gdp))) * xl_number(100.0)


@xl_memoize
def macrofiscal_interest_rate(ctx: EvalContext, time_period: int) -> float:
    """Computes the macrofiscal interest rate as a percentage.

Args:
    ctx: Workbook evaluation context.
    time_period: Projection year (integer, 2009-2029).

Returns:
    Interest rate (percentage).

Note:
    Covers Macrofiscal!K18:AE18. Excel: =Macrofiscal!AA11/Macrofiscal!AA10*100.
"""
    interest_expenditure = macrofiscal_interest_expenditure_lcu(ctx, time_period=time_period)
    debt = macrofiscal_debt_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(interest_expenditure), xl_number(debt))) * xl_number(100.0)


