@xl_memoize
def macrofiscal_primary_expenditure_lcu(ctx: EvalContext, time_period: int) -> float:
    """Compute macrofiscal primary expenditure in local currency units (LCU).

Args:
    ctx: Workbook evaluation context.
    time_period: Projection year (observed range 2009–2029).

Returns:
    Primary expenditure value (LCU billions).

Note:
    Covers Macrofiscal!K12:AE12. Excel: =Macrofiscal!AA7-Macrofiscal!AA11.
"""
    total_expenditure = macrofiscal_expenditure_lcu(ctx, time_period=time_period)
    interest_expenditure = macrofiscal_interest_expenditure_lcu(ctx, time_period=time_period)
    return xl_number(total_expenditure) - xl_number(interest_expenditure)


@xl_memoize
def macrofiscal_interest_expenditure_lcu(ctx: EvalContext, time_period: int) -> float:
    """Compute interest expenditure in local currency units as the difference between the primary balance and the overall balance.

Args:
    ctx: Workbook evaluation context.
    time_period: Year for which to compute interest expenditure (observed range: 2009..2029).

Returns:
    Interest expenditure in LCU billions.

Note:
    Covers Macrofiscal!K11:AE11. Excel: =Macrofiscal!AA9-Macrofiscal!AA8.
"""
    primary_balance = macrofiscal_primary_balance_lcu(ctx, time_period=time_period)
    overall_balance = macrofiscal_overall_balance_lcu(ctx, time_period=time_period)
    return xl_number(primary_balance) - xl_number(overall_balance)


