    debt_lcu = macrofiscal_debt_lcu(ctx, time_period=time_period)
    nominal_gdp_lcu = macrofiscal_nominal_gdp_lcu(ctx, time_period=time_period)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(debt_lcu), xl_number(nominal_gdp_lcu))) * xl_number(100.0)


