@xl_memoize
def inflation_convergence_trajectory(ctx: EvalContext, time_period: int) -> float:
    """Compute the inflation convergence trajectory for a given time period.

Args:
    ctx (EvalContext): The evaluation context for reading cell values.
    time_period (int): The projection year for which the inflation rate is computed. Observed range: 2002 to 2026.

Returns:
    float: The inflation convergence trajectory value for the specified time period.

Note:
    Covers Inflation!B9:Z9. Excel: =Dashboard!C24+(Dashboard!C25-Dashboard!C24)*((1/(1+EXP(-Inflation!G6*(Inflation!B8-Inflation!J6)))^Inflation!G6)).
"""
    inflation_start = read_inflation_start(ctx)
    inflation_end = read_inflation_end(ctx)
    inflation_start_for_diff = read_inflation_start(ctx)
    convergence_steepness = read_inflation_convergence_logistic_steepness(ctx)
    period_index = read_inflation_convergence_period_index(ctx, time_period=time_period)
    midpoint = read_inflation_convergence_logistic_midpoint(ctx)
    logistic_exp = xl_exp(xl_number(-xl_number(convergence_steepness)) * xl_number(xl_number(period_index) - xl_number(midpoint)))
    convergence_steepness_power = read_inflation_convergence_logistic_steepness(ctx)
    return xl_number(inflation_start) + xl_number(xl_number(xl_number(inflation_end) - xl_number(inflation_start_for_diff)) * xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(1.0), xl_number(xl_pow_numbers(xl_number(xl_number(1.0) + xl_number(logistic_exp)), xl_number(convergence_steepness_power))))))


@xl_memoize
def inflation_path(ctx: EvalContext, time_period: int) -> float:
    """Compute the inflation rate for a given year using a logistic convergence model.

Args:
    time_period (int): The projection year (observed range 2055–2099).

Returns:
    CellValue: The computed inflation rate for the given year.

Note:
    Covers Inflation!BC3:CU3. Excel: =(Dashboard!C24+(Dashboard!C25-Dashboard!C24)*((1/(1+EXP(-Inflation!G6*(Inflation!AA8-Inflation!J6)))^Inflation!G6))).
"""
    start_rate = read_inflation_start(ctx)
    end_rate = read_inflation_end(ctx)
    start_rate_diff = read_inflation_start(ctx)
    steepness = read_inflation_convergence_logistic_steepness(ctx)
    adjusted_period_idx = read_inflation_convergence_period_index(ctx, time_period=time_period - 28)
    midpoint = read_inflation_convergence_logistic_midpoint(ctx)
    logistic_exp = xl_exp(xl_number(-xl_number(steepness)) * xl_number(xl_number(adjusted_period_idx) - xl_number(midpoint)))
    steepness_power = read_inflation_convergence_logistic_steepness(ctx)
    return xl_number(start_rate) + xl_number(xl_number(xl_number(end_rate) - xl_number(start_rate_diff)) * xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(1.0), xl_number(xl_pow_numbers(xl_number(xl_number(1.0) + xl_number(logistic_exp)), xl_number(steepness_power))))))


