@xl_memoize
def demography_total_population(ctx: EvalContext, time_period: int) -> str | CellValue:
    '''Return total population for the selected demographic scenario and time period.

Args:
    ctx: Workbook evaluation context.
    time_period: Projection year, from 2008 to 2099.

Returns:
    Total population in thousands of persons for the given time period and selected scenario.

Note:
    Covers Demography!BI4:EV4. Excel: =IF(Dashboard!C17=Demography!B8,Demography!BI12,IF(Dashboard!C17=Demography!B9,Demography!BI13,IF(Dashboard!C17=Demography!B10,Demography!BI14,""""))).
'''
    scenario = read_demography_scenario(ctx)
    medium_label = read_demography_variant_label_medium(ctx)
    return demography_total_population_medium(ctx, time_period=time_period) if (is_medium := xl_bool(xl_compare('=', scenario, medium_label))) else demography_total_population_high(ctx, time_period=time_period) if (is_high := xl_bool(xl_compare('=', read_demography_scenario(ctx), read_demography_variant_label_high(ctx)))) else demography_total_population_low(ctx, time_period=time_period) if (is_low := xl_bool(xl_compare('=', read_demography_scenario(ctx), read_demography_variant_label_low(ctx)))) else '"'


@xl_memoize
def climate_database_labour_productivity_growth_variation_hot_unadapted(ctx: EvalContext, time_period: int) -> float:
    """Compute the variation on labour productivity growth for the hot unadapted scenario.

Args:
    ctx: Workbook evaluation context.
    time_period: Projection year (2030..2099).

Returns:
    Growth variation as percentage points (float).

Note:
    Covers 'Climate Database'!R22:CI22. Excel: ='Climate Database'!AA15/'Climate Database'!Z15*100-100.
"""
    if time_period in {2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098}:
        current_gdp_index = climate_database_gdp_index_hot_unadapted(ctx, time_period=time_period)
        previous_gdp_index = climate_database_gdp_index_hot_unadapted(ctx, time_period=time_period - 1)
        return xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(current_gdp_index), xl_number(previous_gdp_index))) * xl_number(100.0)) - xl_number(100.0)
    if time_period == 2099:
        final_loss_pct = climate_database_gdp_loss_pct_hot_unadapted(ctx, time_period=2099)
        pre_final_gdp_index = climate_database_gdp_index_hot_unadapted(ctx, time_period=2098)
        return xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(100.0) + xl_number(final_loss_pct)), xl_number(pre_final_gdp_index))) * xl_number(100.0)) - xl_number(100.0)
    initial_gdp_index = climate_database_gdp_index_hot_unadapted(ctx, time_period=2030)
    pre_initial_loss_pct = climate_database_gdp_loss_pct_hot_unadapted(ctx, time_period=2029)
    return xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(initial_gdp_index), xl_number(xl_number(100.0) + xl_number(pre_initial_loss_pct)))) * xl_number(100.0)) - xl_number(100.0)


