@xl_memoize
def climate_database_gdp_index_moderate(ctx: EvalContext, time_period: int) -> float:
    """Compute the GDP index for the moderate climate scenario.

Args:
    time_period (int): Projection year in the range 2030..2098.

Returns:
    float: GDP index derived as 100 minus the scenario-specific loss percentage.

Note:
    Covers 'Climate Database'!R11:CH11. Excel: =100+'Climate Database'!AA4.
"""
    gdp_loss_pct = climate_database_gdp_loss_pct_moderate(ctx, time_period=time_period)
    return xl_number(100.0) + xl_number(gdp_loss_pct)


@xl_memoize
def climate_database_labour_productivity_growth_variation_paris(ctx: EvalContext, time_period: int) -> float:
    """Compute the year-on-year variation in labour productivity growth under the Paris scenario.

Args:
    ctx: Workbook evaluation context.
    time_period: Projection year (2030–2099).

Returns:
    Variation in labour productivity growth in percentage points (PP).

Note:
    Covers 'Climate Database'!R17:CI17. Excel: ='Climate Database'!AA10/'Climate Database'!Z10*100-100.
"""
    if time_period in {2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098}:
        current_gdp_index = climate_database_gdp_index_paris(ctx, time_period=time_period)
        previous_gdp_index = climate_database_gdp_index_paris(ctx, time_period=time_period - 1)
        return xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(current_gdp_index), xl_number(previous_gdp_index))) * xl_number(100.0)) - xl_number(100.0)
    if time_period == 2099:
        gdp_loss_pct_2099 = climate_database_gdp_loss_pct_paris(ctx, time_period=2099)
        previous_gdp_index_2098 = climate_database_gdp_index_paris(ctx, time_period=2098)
        return xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number(100.0) + xl_number(gdp_loss_pct_2099)), xl_number(previous_gdp_index_2098))) * xl_number(100.0)) - xl_number(100.0)
    gdp_index_2030 = climate_database_gdp_index_paris(ctx, time_period=2030)
    loss_pct_2029 = climate_database_gdp_loss_pct_paris(ctx, time_period=2029)
    return xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(gdp_index_2030), xl_number(xl_number(100.0) + xl_number(loss_pct_2029)))) * xl_number(100.0)) - xl_number(100.0)


