@xl_memoize
def macrofiscal_interest_growth_differential(ctx: EvalContext) -> float:
    """Compute the interest-growth differential for a given time period.

Args:
    ctx: Workbook evaluation context, providing access to cell values and dependencies.

Returns:
    The interest-growth differential as a float.

Note:
    Covers Macrofiscal!AE23. Excel: =(Macrofiscal!AE18/100-Macrofiscal!AE14/100)/(1+Macrofiscal!AE14/100)*100.
"""
    interest_rate_pct = macrofiscal_interest_rate(ctx, time_period=2029)
    gdp_growth_numerator = macrofiscal_nominal_gdp_growth(ctx, time_period=2029)
    gdp_growth_denominator = macrofiscal_nominal_gdp_growth(ctx, time_period=2029)
    return xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(interest_rate_pct), xl_number(100.0))) - xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(gdp_growth_numerator), xl_number(100.0)))), xl_number(xl_number(1.0) + xl_number((lambda _ln, _rn: _ln / _rn if _rn != 0 else xl_raise(XlError.DIV))(xl_number(gdp_growth_denominator), xl_number(100.0)))))) * xl_number(100.0)


